const request = require('request');

const options = {
  method: 'GET',
  url: 'http://localhost:8080/rest/v2.0/companies/1234/assets/settings/naming_standard/codes',
  qs: {field_name: 'SOME_STRING_VALUE'},
  headers: {
    'Procore-Company-Id': 'SOME_INTEGER_VALUE',
    'Accept-Language': 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("http://localhost:8080/rest/v2.0/companies/1234/assets/settings/naming_standard/codes?field_name=SOME_STRING_VALUE"),
    Headers =
    {
        { "Procore-Company-Id", "SOME_INTEGER_VALUE" },
        { "Accept-Language", "SOME_STRING_VALUE" },
    },
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

const request = require('request');

const options = {
  method: 'PUT',
  url: 'http://localhost:8080/rest/v2.0/companies/1234/assets/settings/naming_standard/codes',
  headers: {
    'Procore-Company-Id': 'SOME_INTEGER_VALUE',
    'Accept-Language': 'SOME_STRING_VALUE',
    'content-type': 'application/json'
  },
  body: [{field_name: 'string', entry_id: 'string', code: 'string'}],
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Put,
    RequestUri = new Uri("http://localhost:8080/rest/v2.0/companies/1234/assets/settings/naming_standard/codes"),
    Headers =
    {
        { "Procore-Company-Id", "SOME_INTEGER_VALUE" },
        { "Accept-Language", "SOME_STRING_VALUE" },
    },
    Content = new StringContent("[{\"field_name\":\"string\",\"entry_id\":\"string\",\"code\":\"string\"}]")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

